import { For, Show } from "solid-js";

import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";

import { NarrativeRewardButton } from "#base/ui-next/screens/narrative-events/narrative-reward-button.js";
import { SmallNarrativeEventChoice } from "#base/ui-next/screens/narrative-events/small-narrative-event-model.js";

const AUDIO_GROUP = "small-narrative-event";

export interface NarrativeEventPanelProps {
	bodyText: string;
	titleText?: string;
	choices: SmallNarrativeEventChoice[];
	storyType?: "LIGHT" | "DISCOVERY";
	leaderCiv?: string;
	backgroundImage?: string;
	onChoiceSelected: (choice: SmallNarrativeEventChoice) => void;
	onClose: () => void;
	panelID: string;
}

export const NarrativeEventPanel = (props: NarrativeEventPanelProps) => {
	return (
		<AudioContextProvider segment={AUDIO_GROUP}>
			<div class="relative">
				<div
					class="img-small-narrative-frame w-full min-h-48 relative flex flex-col max-w-full max-h-full pointer-events-auto"
					style={{
						...(props.backgroundImage ? { "background-image": props.backgroundImage } : {}),
					}}
				>
					<div class="flex flex-row absolute self-center justify-center items-center w-full -top-14 h-8">
						<div class="absolute top-2 left-0\.5 bottom-0 w-1\/2 h-14 img-small-narrative-header" />
						<div class="absolute top-2 right-0 bottom-0 w-1\/2 rotate-y-180 h-14 img-small-narrative-header" />
						<div class="img-small-narrative-top-icon w-8 h-8 top-3 absolute" />
					</div>
					<div class="flex px-4 pt-5">
						<div class="w-full text-center font-body-sm">
							<Show when={props.titleText && props.titleText.length > 0}>
								<L10n.Stylize
									class="pt-2 pb-1 pr-9 pl-4 text-center font-title-lg font-bold tracking-150"
									text={props.titleText!}
								/>
							</Show>
							<L10n.Stylize
								class="pt-3 pb-2 pr-9 pl-4 text-center"
								text={props.bodyText}
							/>
							<Panel
								autoFocus={true}
								class="w-full mt-3 px-3 flex flex-col"
								name="small-narrative-event"
								id={props.panelID}
							>
								<For each={props.choices}>
									{(choice) => (
										<NarrativeRewardButton
											mainText={choice.mainText}
											actionText={choice.actionText}
											rewardText={choice.rewardText}
											icons={choice.icons}
											leaderCiv={props.leaderCiv}
											storyType={props.storyType}
											canAfford={choice.canAfford}
											audioGroup={AUDIO_GROUP}
											onActivate={() => props.onChoiceSelected(choice)}
										/>
									)}
								</For>
							</Panel>
						</div>
					</div>
				</div>
				<CloseButton
					class="absolute top-1 right-1 z-10"
					data-audio-group-ref={AUDIO_GROUP}
					onActivate={props.onClose}
				/>
			</div>
		</AudioContextProvider>
	);
};
